import { defineConfig, loadEnv } from 'vite'
import vue from '@vitejs/plugin-vue'

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, process.cwd(), 'ADMIN_V2_')
  const proxyTarget = env.ADMIN_V2_DEV_PROXY_TARGET

  return {
    base: './',
    plugins: [vue()],
    resolve: {
      alias: {
        '@': new URL('./src', import.meta.url).pathname,
      },
    },
    server: {
      host: '0.0.0.0',
      port: 8090,
      strictPort: true,
      proxy: proxyTarget
        ? {
            '/api': {
              target: proxyTarget,
              changeOrigin: true,
              secure: false,
              rewrite: (path) => path.replace(/^\/api/, ''),
            },
          }
        : undefined,
    },
    preview: {
      port: 8091,
      strictPort: true,
    },
    build: {
      outDir: 'dist',
      emptyOutDir: true,
      sourcemap: false,
      reportCompressedSize: true,
    },
  }
})
import fs from 'node:fs/promises'
import path from 'node:path'
import crypto from 'node:crypto'

const distDir = path.resolve(process.argv[2] || 'dist')
const manifestPath = path.join(distDir, 'integrity-manifest.json')
const manifest = JSON.parse(await fs.readFile(manifestPath, 'utf8'))
const failures = []

for (const record of manifest.files || []) {
  const absolute = path.resolve(distDir, record.path)
  if (!absolute.startsWith(`${distDir}${path.sep}`)) {
    failures.push(`잘못된 경로: ${record.path}`)
    continue
  }
  try {
    const content = await fs.readFile(absolute)
    const digest = crypto.createHash('sha256').update(content).digest('hex')
    if (digest !== record.sha256 || content.byteLength !== record.size) failures.push(`checksum 불일치: ${record.path}`)
  } catch {
    failures.push(`파일 없음: ${record.path}`)
  }
}

if (failures.length) {
  console.error(failures.join('\n'))
  process.exit(1)
}

console.log(`[integrity] OK: ${manifest.files.length} files`)
import fs from 'node:fs/promises'
import path from 'node:path'

const distDir = path.resolve(process.argv[2] || 'dist')
const required = ['index.html', 'config/runtime.json']
const failures = []

for (const relative of required) {
  try {
    await fs.access(path.join(distDir, relative))
  } catch {
    failures.push(`필수 파일 없음: ${relative}`)
  }
}

async function walk(dir) {
  const entries = await fs.readdir(dir, { withFileTypes: true })
  const files = []
  for (const entry of entries) {
    const absolute = path.join(dir, entry.name)
    if (entry.isDirectory()) files.push(...(await walk(absolute)))
    else files.push(absolute)
  }
  return files
}

for (const file of await walk(distDir)) {
  if (/\.map$/i.test(file)) {
    failures.push(`source map 포함: ${path.relative(distDir, file)}`)
    continue
  }
  if (!/\.(?:html|css)$/i.test(file)) continue
  const text = await fs.readFile(file, 'utf8')
  const relative = path.relative(distDir, file)
  if (/(?:src|href)\s*=\s*["'](?:https?:)?\/\//i.test(text)) failures.push(`외부 asset URL: ${relative}`)
  if (/url\(\s*["']?https?:\/\//i.test(text)) failures.push(`외부 CSS URL: ${relative}`)
  if (/@import\s+(?:url\()?\s*["']?(?:https?:)?\/\//i.test(text)) failures.push(`외부 CSS import: ${relative}`)
}

const index = await fs.readFile(path.join(distDir, 'index.html'), 'utf8').catch(() => '')
if (/\b(?:src|href)=["']\//i.test(index)) failures.push('index.html에 root 절대 asset 경로가 있습니다.')

if (failures.length) {
  console.error(failures.join('\n'))
  process.exit(1)
}

console.log('[offline] OK: 외부 asset 참조 없음, 상대 경로 배포 가능')

